+const wetAfternoon: HourCell[] = [
+  { hh: "09:00", tempC: 14, rain: false, isNow: true },
+  { hh: "12:00", tempC: 17, rain: false, isNow: false },
+  { hh: "15:00", tempC: 16, rain: true, isNow: false },
+  { hh: "21:00", tempC: 12, rain: true, isNow: false },
