+    { hh: "21:00", tempC: 12, rain: true, isNow: false },
+  ];
+  expect(rainAheadFor("work", wetNightOnly)).toBe(false);
+  expect(rainAheadFor("evening", wetNightOnly)).toBe(true);
+});
