90	
91	    // THE CACHE. Checked before the quota is touched and before any I/O beyond
92	    // this one indexed lookup — re-opening an answer you already have must never
93	    // cost anything.
94	    // A regenerate deliberately skips the cache — that is the whole point of
95	    // the control. Everything else is a free read, per Decision 5.
96	    const cached = opts?.regenerate ? [] : await loadStyledLooks(user.id, itemId, today);
