204	      if (pinned.length) break;
205	    }
206	
207	    if (!pinned.length) {
208	      return {
209	        status: "empty",
210	        message: "Not enough other pieces to build a look around this one yet.",
211	      };
212	    }
213	
214	    const byId = new Map(items.map((i) => [i.id, i]));
215	    // Diversified, exactly as the daily path does it. A raw slice hands the
216	    // model twenty variations of one idea, because ranking clusters.
217	    const shortlist = shortlistFor(pinned);
218	
219	    const { picks } = await rerank({
220	      want: STYLED_LOOKS,
221	      combos: shortlist.map((t) =>
222	        t.items.map((ci) => {
223	          const it = byId.get(ci.id)!;
