225	            category: it.category,
226	            subcategory: it.subcategory,
227	            colors: it.colors ?? [],
228	            material: it.material,
229	            texture: it.texture,
230	            pattern: it.pattern,
231	          };
232	        }),
233	      ),
234	      aesthetic,
235	      occasion,
236	      weatherLabel: f.condition,
