273	      ),
274	      aesthetic,
275	      occasion: input.occasion,
276	      weatherLabel: f.condition,
277	      // The temperature the shortlist was BUILT for, not the current reading —
278	      // otherwise the "why" describes a different day from the outfit.
279	      tempC: planningTemp(candidateArgs.weather),
280	      nowC: f.tempC,
