299	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
300	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
301	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
302	        itemId: d.id,
303	        category: d.category,
304	        subcategory: d.subcategory ?? null,
305	        brand: d.brand ?? null,
306	        name: d.name ?? null,
307	        colors: d.colors ?? [],
308	        cutoutUrl: signed.get(displayPath(d)) ?? "",
