314	    // Fire-and-forget would be simpler, but a failed write means the user pays
315	    // for another AI call on their next tap — worth awaiting. The insert also
316	    // hands back the row ids, which are the detail screen's address.
317	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
318	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
