52	  locationOrigin: "geo" | "city" | "profile" | "default";
53	  laterSentence: string; // full: "Rain from 21:00 — take a shell."
54	  adviceClause: string; // JUST the rust clause: "take a shell." — the UI binds the rust <b> to THIS
